import mongoose, { Schema, Document, Model } from 'mongoose';

export interface IEvent extends Document {
  name: string;
  description: string;
  venue: {
    address: string;
    googleMapsLink: string;
  };
  date: Date;
  startTime: string;
  batchSize: number;
  gapBetweenBatches: number;
  maxParticipants: number;
  currentParticipants: number;
  status: 'upcoming' | 'ongoing' | 'completed' | 'cancelled';
  price: number;
  image: string;
  createdAt: Date;
  createdBy: mongoose.Types.ObjectId;
}

const eventSchema = new Schema<IEvent>({
  name: {
    type: String,
    required: [true, 'Please add an event name'],
    trim: true,
  },
  description: {
    type: String,
    required: [true, 'Please add a description'],
  },
  venue: {
    address: {
      type: String,
      required: [true, 'Please add a venue address'],
    },
    googleMapsLink: {
      type: String,
      required: [true, 'Please add a Google Maps link'],
    },
  },
  date: {
    type: Date,
    required: [true, 'Please add an event date'],
  },
  startTime: {
    type: String,
    required: [true, 'Please add a start time (e.g., 06:00)'],
  },
  batchSize: {
    type: Number,
    default: 10,
  },
  gapBetweenBatches: {
    type: Number,
    required: [true, 'Please add time gap between batches in minutes'],
  },
  maxParticipants: {
    type: Number,
    required: [true, 'Please add maximum total participants'],
  },
  currentParticipants: {
    type: Number,
    default: 0,
  },
  status: {
    type: String,
    enum: ['upcoming', 'ongoing', 'completed', 'cancelled'],
    default: 'upcoming',
  },
  price: {
    type: Number,
    required: [true, 'Please add a registration price'],
    default: 0,
  },
  image: {
    type: String,
    default: '/images/current-event.jpg',
  },
  createdAt: {
    type: Date,
    default: Date.now,
  },
  createdBy: {
    type: Schema.Types.ObjectId,
    ref: 'User',
    required: true,
  },
});

const Event: Model<IEvent> = mongoose.models.Event || mongoose.model<IEvent>('Event', eventSchema);
export default Event;
